  7	+import { App } from "obsidian";
  8	+import { useEffect, useRef, type KeyboardEvent, type ReactElement } from "react";
  9	+import { SearchDropdown } from "~/components/SearchDropdown";
 10	+
 11	+/**
 12	+ * Obsidian's native toggle look: `checkbox-container`'s own onClick, not just the
 13	+ * input's onChange — the input alone stops responding after one click. `role="switch"`
 14	+ * plus `aria-checked` gives it proper switch semantics, and the input keeps native
 15	+ * Tab/Space handling (Enter is added on top, matching this app's other dropdown rows).
 16	+ *
 17	+ * The input is `pointer-events-none`, so a mouse click always lands on this
 18	+ * container (Obsidian's own CSS positions the invisible, `opacity:0` input to
 19	+ * cover the whole pill, so without this every mouse click would land on the
 20	+ * input instead) — making the container the sole mouse-click handler, while
 21	+ * keyboard Space-bar toggling still reaches the input directly (unaffected by
 22	+ * `pointer-events`) and is let through via the `event.target === inputRef.current`
 23	+ * check below, which this onClick skips for that one case so the two never
 24	+ * both fire for the same interaction.
 25	+ *
 26	+ * The focus ring is plain CSS `:focus-visible` (via Tailwind's `has-[:focus-visible]:`,
 27	+ * since the ring must show on this container, not the invisible `opacity:0` input
 28	+ * itself) — deliberately not `:focus`/`:focus-within`, which fired for a mouse click
 29	+ * too. `:focus-visible` is the browser's own "was this keyboard navigation" heuristic,
 30	+ * so a click never shows it. If this ever renders unreliably in this app's cascade the
 31	+ * way `:focus-within` once did elsewhere, fall back to the JS-tracked-input-modality
 32	+ * approach used for `NodeSortMenu`'s rows instead.
 33	+ *
 34	+ * `mod-small`, matching the toggle size Obsidian's own built-in search settings
 35	+ * popover uses (`.checkbox-container.mod-small` in app.css) — this menu is the
 36	+ * same kind of small settings popover, not a full Settings-tab row, so the
 37	+ * bigger default toggle read as oversized here.
 38	+ */
 39	+const ToggleRow = ({
 40	+  autoFocus = false,
 41	+  checked,
 42	+  label,
 43	+  onChange,
 44	+}: {
 45	+  /** Only the panel's first row should claim focus on open — a second `ToggleRow` mounting after it would otherwise steal focus right back. */
 46	+  autoFocus?: boolean;
 47	+  checked: boolean;
 48	+  label: string;
 49	+  onChange: (checked: boolean) => void;
 50	+}): ReactElement => {
 51	+  const inputRef = useRef<HTMLInputElement | null>(null);
 52	+
 53	+  useEffect(() => {
 54	+    if (autoFocus) inputRef.current?.focus();
 55	+  }, [autoFocus]);
 56	+
 57	+  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>): void => {
 58	+    if (event.key !== "Enter") return;
 59	+    event.preventDefault();
 60	+    onChange(!checked);
 61	+  };
 62	+
 63	+  return (
 64	+    <div className="flex items-center justify-between gap-[var(--size-4-3)] px-[var(--size-4-3)] py-[var(--size-2-3)]">
 65	+      {/* Not a `<label htmlFor>`: that would let a text click fire the input's own
 66	+          onChange *in addition to* the container's onClick below, double-toggling —
 67	+          same reason apps/obsidian/src/components/GeneralSettings.tsx's ToggleSetting
 68	+          uses a plain div here instead. */}
 69	+      <span className="text-normal text-[length:var(--font-ui-small)]">
 70	+        {label}
 71	+      </span>
 72	+      <div
 73	+        role="switch"
 74	+        aria-checked={checked}
 75	+        className={`checkbox-container mod-small has-[:focus-visible]:outline has-[:focus-visible]:outline-2 has-[:focus-visible]:outline-offset-[-2px] has-[:focus-visible]:outline-[color:var(--background-modifier-border-focus)] ${checked ? "is-enabled" : ""}`}
 76	+        // The container itself has no `tabIndex`, so it can never be a focus
 77	+        // destination — clicking it still blurs whatever *was* focused (the
 78	+        // browser's default mousedown behavior for a non-focusable target),
 79	+        // and nothing re-focuses afterward, since there's no native
 80	+        // "activation" for a plain div the way there is for a real form
 81	+        // control. Left alone, that permanently drops focus to
 82	+        // `document.body`, which `SearchDropdown`'s panel reads as "focus
 83	+        // left" and closes on — before this onClick even runs. Suppressed by
 84	+        // preventing that default mousedown behavior, exactly like
 85	+        // `SearchDropdown`'s own trigger button already does to protect the
 86	+        // search input's focus.
 87	+        onMouseDown={(event) => event.preventDefault()}
 88	+        onClick={(event) => {
 89	+          if (event.target === inputRef.current) return;
 90	+          onChange(!checked);
 91	+        }}
 92	+      >
 93	+        <input
 94	+          ref={inputRef}
 95	+          type="checkbox"
 96	+          checked={checked}
 97	+          aria-label={label}
 98	+          onChange={(event) => onChange(event.target.checked)}
 99	+          onKeyDown={handleKeyDown}
100	+          className="pointer-events-none"
101	+        />
102	+      </div>
103	+    </div>
104	+  );
105	+};
