    setTagCandidateState({ status: "loading" });
    void new QueryEngine(app)
      .getDiscourseTagCandidates(plugin.settings.nodeTypes)
      .then((candidates) => {
        settled = true;
        if (!cancelled) setTagCandidateState({ status: "ready", candidates });
