      .catch((error: unknown) => {
        settled = true;
        if (cancelled) return;
        const message =
          error instanceof Error ? error.message : "Unexpected error";
        new Notice(`Could not load tagged lines: ${message}`);
        setTagCandidateState({ status: "error", message });
