      cancelled = true;
      // Reset the fetch guard so that any dependency change (nodeTypes config
      // update, or toggling showTags off before the scan finishes) allows a
      // fresh fetch on the next render. A settled result is not cached across
      // dependency changes because stale candidates would be shown if nodeTypes
      // changed after a successful fetch.
      hasFetchedTagCandidatesRef.current = false;
